const j = pm.response.json();
const ev = ["syncerror", "heartbeat", "userlogout", "userhibernate", "Patient-open", "Patient-close", "ImagingStudy-open", "ImagingStudy-close", "Encounter-open", "Encounter-close", "DiagnosticReport-open", "DiagnosticReport-close", "DiagnosticReport-select", "DiagnosticReport-update"];
pm.test('eventsSupported đủ 14 sự kiện theo thứ tự công bố', () => pm.expect(j.eventsSupported).to.eql(ev));
pm.test('websocketSupport true, webhookSupport false', () => { pm.expect(j.websocketSupport).to.eql(true); pm.expect(j.webhookSupport).to.eql(false); });
pm.test('mọi khóa nằm trong tập đã công bố', () => { const ks = Object.keys(j).sort(); pm.expect(ks).to.eql(["eventsSupported", "fhircastVersion", "webhookSupport", "websocketSupport"]); });
pm.test('Content-Type application/json', () => pm.expect(pm.response.headers.get('Content-Type')).to.include('application/json'));

